UPDATE public.au_events SET status='tested' WHERE code LIKE 'ds.api.%' AND code NOT IN ('ds.api.admin_requests','ds.api.gifted_programs','ds.api.guidance_programs','ds.api.hr_leaves','ds.api.hr_vacancies','ds.api.hr_attendance','ds.api.hr_assets','ds.api.notices');
UPDATE public.au_sources SET status='tested' WHERE event_code LIKE 'ds.api.%' AND event_code NOT IN ('ds.api.admin_requests','ds.api.gifted_programs','ds.api.guidance_programs','ds.api.hr_leaves','ds.api.hr_vacancies','ds.api.hr_attendance','ds.api.hr_assets','ds.api.notices');
UPDATE public.au_sources SET reason='مربوط؛ لا توجد سجلات في قاعدة الاختبار للتحقق منه ببيانات' WHERE event_code IN ('ds.api.admin_requests','ds.api.gifted_programs','ds.api.guidance_programs','ds.api.hr_leaves','ds.api.hr_vacancies','ds.api.hr_attendance','ds.api.hr_assets','ds.api.notices');